import sys

def main():
    flags = []
    filepath = None
    args = sys.argv[1:]
    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith('-') and arg != '-' and not arg.startswith('--'):
            # Parse combined flags like -lw or -l -w
            for ch in arg[1:]:
                if ch in ('l', 'w', 'c'):
                    flags.append(ch)
                else:
                    print(f"wc: invalid option: -{ch}", file=sys.stderr)
                    sys.exit(1)
        elif arg == '-':
            filepath = '-'
        elif filepath is None:
            filepath = arg
        else:
            print(f"wc: extra operand: {arg}", file=sys.stderr)
            sys.exit(1)
        i += 1

    if not flags:
        flags = ['l', 'w', 'c']

    if filepath is None:
        import io
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, 'rb') as f:
            data = f.read()

    line_count = data.count(b'\n')
    # If the file doesn't end with a newline but has content, count that last partial line
    if len(data) > 0 and not data.endswith(b'\n'):
        line_count += 1

    word_count = len(data.decode('utf-8', errors='surrogateescape').split())
    char_count = len(data)

    outputs = []
    for flag in flags:
        if flag == 'l':
            outputs.append(str(line_count))
        elif flag == 'w':
            outputs.append(str(word_count))
        elif flag == 'c':
            outputs.append(str(char_count))

    print(' '.join(outputs))

if __name__ == '__main__':
    main()

